pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor, address receiver) public {
        vm.assume(actor != address(0));
        vm.assume(receiver != address(0));
        vm.assume(receiver != actor);
        vm.assume(receiver.code.length == 0); // plain payable recipient
        amount = bound(amount, 1, 1e30);
        vm.deal(actor, 1 ether);
        vm.deal(address(c), amount + 2); // enough even for the mutant
        vm.prank(actor);
        bool ok;
        try c.sendTo(receiver, amount) { ok = true; } catch { ok = false; }
        if (ok) {
            uint256 recvBal = receiver.balance;
            assertTrue(
                recvBal == amount && address(c).balance == 2,
                "successful sendTo must transfer exactly amount"
            );
        } else {
            assertTrue(false, "owner sendTo with sufficient funding must succeed");
        }
    }
}

