pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 offset, address receiver) public {
        // admissible domain: positive amount, non-zero receiver
        amount = bound(amount, 1, 1e30);
        vm.assume(receiver != address(0));
        // balance is fuzzed to sit exactly at, or just above, the admissible threshold:
        // offset 0 -> balance == amount (the deciding case), 1 or 2 -> comfortably above
        offset = bound(offset, 0, 2);
        uint256 bal = amount + offset;
        vm.deal(address(c), bal);

        // constructor set owner = msg.sender (this test contract), so call directly
        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // RULE: with a non-zero receiver, positive amount, and caller == owner,
        // sendTo must succeed whenever the contract's balance is >= amount.
        assertTrue(ok, "sendTo must succeed when balance >= amount");
    }
}

