import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        vm.deal(address(c), 100 ether);
    }
    function testFuzz_property(address actor, address receiver, uint96 amount) public {
        vm.assume(actor != c.owner());
        vm.assume(amount > 0 && amount <= address(c).balance);
        uint balBefore = address(c).balance;
        vm.prank(actor);
        bool ok;
        try c.sendTo(receiver, amount) { ok = true; } catch { ok = false; }
        assertFalse(ok);
        assertTrue(address(c).balance == balBefore);
    }
