contract InvMutTest {

    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address receiver, uint amount) public {
        require(amount > 0);
        require(receiver != address(0));

        // Setup: if this contract happens to be c's owner, drain c's balance
        // first so that no funds remain for the subsequent sendTo. If this
        // contract is not the owner, this top-level call reverts and the
        // assertion is never reached.
        c.sendTo(address(this), address(c).balance);

        require(address(c).balance >= amount);

        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assert(!ok);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address receiver, uint amount) public payable {
        require(receiver == address(0));
        require(amount > 0);
        require(address(this).balance >= amount);
        bool reverted;
        try c.sendTo{value: amount}(receiver, amount) { reverted = false; } catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
}

contract InvMutTest {

    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address receiver, uint amount) public {
        require(receiver != address(0));
        require(amount > 0 && amount <= address(c).balance);

        // This contract is not C's owner, so on the original contract this
        // top-level call must revert and the property holds vacuously.
        c.sendTo(receiver, amount);

        // Reached only if a non-owner successfully moved funds out of C.
        bool ok = address(c).balance < amount;

        assert(!ok);
    }
}
